from pathlib import Path

p=Path('/var/www/hebrewverbs-clean/verbs.html')
s=p.read_text(encoding='utf-8')
start='function request(q){'
end='\nfunction removeRoot(){'
a=s.find(start,s.find('id="hebrew-roots-workspace-code"'))
if a<0: raise SystemExit('СТОП: блок корней не найден; файл не изменён')
b=s.find(end,a)
if b<0: raise SystemExit('СТОП: конец блока корней не найден; файл не изменён')
if 'var rootsAiReady=null' in s[a:b]: raise SystemExit('Уже установлено; изменений нет')
old=s[a:b]
new=" var rootsAiReady=null,rootsAiBusy=false,rootsAiRun=0;\n function rootsNotice(message){\n  var w=workspace(),n=el('rootsAiNotice');\n  if(!n){n=document.createElement('div');n.id='rootsAiNotice';n.style.cssText='text-align:center;font:600 17px/1.35 Arial,sans-serif;padding:8px 5px;white-space:normal';w.append(n)}\n  n.textContent=message;\n }\n function binyanId(value){\n  var v=String(value||'').toLowerCase().replace(/[\\s_\\-\\u05b0-\\u05c7]/g,'');\n  var aliases={paal:'paal',qal:'paal',kal:'paal',פעל:'paal',קל:'paal',nifal:'nifal',נפעל:'nifal',piel:'piel',פיעל:'piel',pual:'pual',פועל:'pual',hifil:'hifil',הפעיל:'hifil',hufal:'hufal',הופעל:'hufal',hitpael:'hitpael',התפעל:'hitpael'};\n  return aliases[v]||'';\n }\n function rootsFromApi(data,query){\n  if(!data||data.section!=='roots'||!Array.isArray(data.entries))throw Error('Некорректный ответ API');\n  var result=[],seen={};\n  data.entries.forEach(function(entry){\n   if(!entry||!entry.he||!entry.grammar)return;\n   var g=entry.grammar,bin=binyanId(g.binyan||g.binyan_id||g.binyanId||g.pattern||g.binyanName);\n   // Only real infinitives with an explicitly identified binyan may be shown.\n   var he=String(entry.he).trim();\n   if(!bin||!/^ל[\\u0591-\\u05c7]*[\\u05d0-\\u05ea]/.test(he))return;\n   var key=bin+'|'+norm(he);if(seen[key])return;seen[key]=true;\n   result.push({binyan:bin,he:he,ru:entry.ru||'',uk:entry.uk||'',en:entry.en||''});\n  });\n  if(!result.length)throw Error('ИИ не указал подтверждённые инфинитивы и биньяны. Попробуйте запрос на иврите.');\n  var root=cleanRoot(data.topic&&data.topic.he);\n  // A root has three Hebrew letters; do not treat an infinitive as a root.\n  if(root.length!==3)root='';\n  return {he:root||query,binyanim:result};\n }\n async function request(q){\n  var query=String(q||selected||'').trim();\n  if(!query){rootsNotice('Выберите глагол из личного списка.');return}\n  if(rootsAiBusy)return;\n  selected=query;temporaryBinyanim=null;rootsAiReady=null;show();\n  var run=++rootsAiRun;rootsAiBusy=true;\n  var ai=el('alwaysAiCodeAI');if(ai){ai.setAttribute('aria-busy','true');ai.classList.add('verb-ai-loading')}\n  rootsNotice('AI определяет корень и биньяны…');\n  try{\n   var topic=('Определи корень глагола '+query+'. Перечисли реальные глаголы этого корня в инфинитиве с огласовками; укажи grammar.binyan для каждого.').slice(0,120);\n   var response=await fetch('/api/ai/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({section:'roots',topic:topic,level:'beginner'}),cache:'no-store'});\n   if(!response.ok)throw Error('HTTP '+response.status);\n   var result=rootsFromApi(await response.json(),query);\n   if(run!==rootsAiRun||!mode)return;\n   rootsAiReady={query:query,data:result};\n   rootsNotice('Готово. Нажмите +, чтобы открыть список биньянов.');\n  }catch(err){if(run===rootsAiRun)rootsNotice('Ошибка: '+err.message)}\n  finally{if(run===rootsAiRun){rootsAiBusy=false;if(ai){ai.removeAttribute('aria-busy');ai.classList.remove('verb-ai-loading')}}}\n }\n function add(){\n  var q=String(el('verbSearch')?.value||selected||'').trim();\n  if(!rootsAiReady||norm(rootsAiReady.query)!==norm(q)){\n   rootsNotice('Сначала нажмите AI и дождитесь результата.');return;\n  }\n  temporaryBinyanim=rootsAiReady.data;\n  selected=rootsAiReady.data.he;\n  pageCollapsed=false;document.body.classList.remove('roots-page-collapsed');\n  show();\n }\n"
s=s[:a]+new+s[b:]
old_input='selected=e.target.value.trim();temporaryBinyanim=null;listing=false;workspace().replaceChildren()'
if s.count(old_input)!=1:raise SystemExit('СТОП: обработчик ввода не найден; файл не изменён')
s=s.replace(old_input,'selected=e.target.value.trim();temporaryBinyanim=null;rootsAiReady=null;rootsAiRun++;listing=false;workspace().replaceChildren()',1)
p.write_text(s,encoding='utf-8')
print('OK: Корни иврита: AI автоматически вызывает API, + открывает биньяны. Остальные разделы не изменены. Без резервной копии.')
